from .syslog_reader import SyslogReader
from .fsyslog_entry import FsyslogEntry


class FsyslogReader(SyslogReader):
    cls = FsyslogEntry

    source_ip_addr_parse_pattern_string = br"(?:(?P<source_ip_addr>\d+\.\d+\.\d+\.\d+) )?"
    source_ip_addr_split_pattern_string = br"(?:\d+\.\d+\.\d+\.\d+ )?"

    _tool_prefix_parse_pattern_string = source_ip_addr_parse_pattern_string
    _tool_prefix_split_pattern_string = source_ip_addr_split_pattern_string
